window.READABILITY_DETAIL = {"ka":"KA-02348","longest":[{"text":"Twenty days after a parking ticket is issued or the date of the NOL, the Department of Finance (DOF) will send a Pre-Penalty Notice of Unpaid Violation to the address on file at the Department of Motor Vehicles (DMV) for the registered owner of the vehicle.","words":46},{"text":"You can contact the Parking Summons Advocate for help if you keep receiving notices from the Department of Finance or a collection agency about a ticket that you already paid or already had a hearing on but for which you never received a decision.","words":44},{"text":"You can contact the Parking Summons Advocate for help if you keep receiving notices from the Department of Finance or a collection agency about a ticket that you already paid or already had a hearing on but for which you never received a decision.","words":44},{"text":"You can contact the Parking Summons Advocate for help if you keep receiving notices from the Department of Finance or a collection agency about a ticket that you already paid or already had a hearing on but for which you never received a decision.","words":44},{"text":"The email lists the license plate of the vehicle with the judgment debt, but any vehicles registered to the same owner are subject to booting or towing, even if they aren't listed on the email or don't have any judgment debt.","words":41}],"blocks":[{"k":"p","c":0,"t":"Need something else?","s":["Need something else?"]},{"k":"p","c":0,"t":"Parking Ticket or Camera Violation Payment to pay a parking ticket or camera violation","s":["Parking Ticket or Camera Violation Payment to pay a parking ticket or camera violation"]},{"k":"p","c":0,"t":"Parking Ticket or Camera Violation Dispute to fight a parking ticket or camera violation","s":["Parking Ticket or Camera Violation Dispute to fight a parking ticket or camera violation"]},{"k":"p","c":0,"t":"Parking Ticket or Camera Violation Status to look up information about your parking or camera violations and get payment, dispute, and appeal status","s":["Parking Ticket or Camera Violation Status to look up information about your parking or camera violations and get payment, dispute, and appeal status"]},{"k":"p","c":0,"t":"Parking Ticket or Camera Violation Copy to get a copy of a parking ticket or bus lane, red light, or speed camera Notice of Liability (NOL)","s":["Parking Ticket or Camera Violation Copy to get a copy of a parking ticket or bus lane, red light, or speed camera Notice of Liability (NOL)"]},{"k":"p","c":0,"t":"Parking Ticket or Camera Violation Clearance to learn what to do if your vehicle's registration has been suspended or put on hold because of unpaid parking or camera judgment debt","s":["Parking Ticket or Camera Violation Clearance to learn what to do if your vehicle's registration has been suspended or put on hold because of unpaid parking or camera judgment debt"]},{"k":"p","c":0,"t":"Parking Ticket or Camera Violation Payment Plan to request to pay in installments if you owe parking or camera violation judgment debt","s":["Parking Ticket or Camera Violation Payment Plan to request to pay in installments if you owe parking or camera violation judgment debt"]},{"k":"p","c":0,"t":"You can get help with a parking or camera violation, payment, or dispute.","s":["You can get help with a parking or camera violation, payment, or dispute."]},{"k":"h","c":0,"t":"Beware of Scams and Fraud"},{"k":"p","c":0,"t":"If you receive a text message claiming to be from “CityPay,” please delete it. CityPay will never send you an unsolicited text message reminding you to make a payment. Do not click any links sent to you in a text claiming to be from CityPay, as this is a scam.","s":["If you receive a text message claiming to be from “CityPay,” please delete it.","CityPay will never send you an unsolicited text message reminding you to make a payment.","Do not click any links sent to you in a text claiming to be from CityPay, as this is a scam."]},{"k":"h","c":0,"t":"Accommodation for People with Disabilities"},{"k":"p","c":1,"t":"If you need help accessing Department of Finance (DOF) programs and services because of a disability or medical condition, you can request a reasonable accommodation.","s":["If you need help accessing Department of Finance (DOF) programs and services because of a disability or medical condition, you can request a reasonable accommodation."]},{"k":"p","c":1,"t":"The Americans with Disabilities Act (ADA) defines a disability as a physical or mental impairment that substantially limits one or more major life activities.","s":["The Americans with Disabilities Act (ADA) defines a disability as a physical or mental impairment that substantially limits one or more major life activities."]},{"k":"p","c":1,"t":"This includes physical disorders affecting the:","s":["This includes physical disorders affecting the:"]},{"k":"h","c":1,"t":"Brain"},{"k":"h","c":1,"t":"Muscles"},{"k":"h","c":1,"t":"Eyes"},{"k":"h","c":1,"t":"Ears"},{"k":"h","c":1,"t":"Nose"},{"k":"h","c":1,"t":"Mouth"},{"k":"h","c":1,"t":"Respiratory system"},{"k":"h","c":1,"t":"Cardiovascular system"},{"k":"h","c":1,"t":"Skin"},{"k":"p","c":1,"t":"To learn how to request a reasonable accommodation from DOF or to make a complaint if you feel a DOF program or service isn’t accessible to you, visit the Access City Agencies as a Person with a Disability page.","s":["To learn how to request a reasonable accommodation from DOF or to make a complaint if you feel a DOF program or service isn’t accessible to you, visit the Access City Agencies as a Person with a Disability page."]},{"k":"h","c":1,"t":"Sign Language Interpretation"},{"k":"p","c":1,"t":"You can request a sign language interpreter for transactions at the Department of Finance, including parking ticket hearings and appeals.","s":["You can request a sign language interpreter for transactions at the Department of Finance, including parking ticket hearings and appeals."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"You can request a sign language interpreter online for Parking Ticket or Property Tax Services. To schedule an appointment and request a sign language interpreter online, go to the DOF Business Center page.","s":["You can request a sign language interpreter online for Parking Ticket or Property Tax Services.","To schedule an appointment and request a sign language interpreter online, go to the DOF Business Center page."]},{"k":"h","c":1,"t":"By Phone"},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) for help.","s":["Call 311 or 212-NEW-YORK (212-639-9675) for help."]},{"k":"h","c":0,"t":"Bounced Payment"},{"k":"p","c":1,"t":"After receiving your payment, the Department of Finance (DOF) will present it to your bank so the funds can be withdrawn. If there isn’t enough money available to cover the balance, DOF will automatically attempt to collect the funds again on the following business day.","s":["After receiving your payment, the Department of Finance (DOF) will present it to your bank so the funds can be withdrawn.","If there isn’t enough money available to cover the balance, DOF will automatically attempt to collect the funds again on the following business day."]},{"k":"p","c":1,"t":"If your payment bounces and this causes your payment to be late, DOF may charge you penalties and interest. You should also contact your bank with questions about its policy on bounced payments.","s":["If your payment bounces and this causes your payment to be late, DOF may charge you penalties and interest.","You should also contact your bank with questions about its policy on bounced payments."]},{"k":"h","c":1,"t":"eCheck Payments"},{"k":"p","c":1,"t":"If an eCheck payment can’t be processed, DOF will send you an email with information about your returned payment. The original amount due will be reinstated, as well as any late fees, penalties, or booting fees that had been charged at the time of your original payment. It can take up to 5 days for the reinstated charges to be available for online payment in CityPay or the mobile app.","s":["If an eCheck payment can’t be processed, DOF will send you an email with information about your returned payment.","The original amount due will be reinstated, as well as any late fees, penalties, or booting fees that had been charged at the time of your original payment.","It can take up to 5 days for the reinstated charges to be available for online payment in CityPay or the mobile app."]},{"k":"p","c":1,"t":"If you receive this email, you need to submit another payment. If you don't, additional penalties and interest will be charged, along with the original amount due, until you make the payment and it is collected by DOF.","s":["If you receive this email, you need to submit another payment.","If you don't, additional penalties and interest will be charged, along with the original amount due, until you make the payment and it is collected by DOF."]},{"k":"p","c":1,"t":"If you have three or more returned eCheck payments within a 6-month period, you will be blocked from online payment. The block will be removed once your debt is cleared for 15 consecutive calendar days.","s":["If you have three or more returned eCheck payments within a 6-month period, you will be blocked from online payment.","The block will be removed once your debt is cleared for 15 consecutive calendar days."]},{"k":"h","c":0,"t":"Credit or Debit Cards"},{"k":"p","c":1,"t":"The first thing you may want to do if you’ve encountered a problem paying with a credit or debit card is to check the status of your violation.","s":["The first thing you may want to do if you’ve encountered a problem paying with a credit or debit card is to check the status of your violation."]},{"k":"p","c":1,"t":"You can also check your credit or debit card account to verify that your payment was processed.","s":["You can also check your credit or debit card account to verify that your payment was processed."]},{"k":"p","c":1,"t":"Look up your parking tickets or camera violations.","s":["Look up your parking tickets or camera violations."]},{"k":"h","c":1,"t":"Declined Payments"},{"k":"p","c":1,"t":"If a Credit or Debit Card payment can’t be processed, DOF will send you an email with information about your returned payment. The original amount due will be reinstated, as well as any late fees, penalties, or booting fees that had been charged at the time of your original payment. It can take up to 5 days for the reinstated charges to be available for online payment in CityPay or the mobile app.","s":["If a Credit or Debit Card payment can’t be processed, DOF will send you an email with information about your returned payment.","The original amount due will be reinstated, as well as any late fees, penalties, or booting fees that had been charged at the time of your original payment.","It can take up to 5 days for the reinstated charges to be available for online payment in CityPay or the mobile app."]},{"k":"p","c":1,"t":"If you receive this email, you need to submit another payment. If you don't, additional penalties and interest will be charged, along with the original amount due, until you make the payment and it is collected by DOF.","s":["If you receive this email, you need to submit another payment.","If you don't, additional penalties and interest will be charged, along with the original amount due, until you make the payment and it is collected by DOF."]},{"k":"h","c":1,"t":"Billing and Address Mismatch"},{"k":"p","c":1,"t":"Make sure that you’ve entered your address exactly how it appears on your credit card or debit card statement. Your card may be rejected if you enter an address that doesn’t match your bank or credit card company’s records.","s":["Make sure that you’ve entered your address exactly how it appears on your credit card or debit card statement.","Your card may be rejected if you enter an address that doesn’t match your bank or credit card company’s records."]},{"k":"p","c":1,"t":"If you entered your address correctly and the payment was rejected, you need to contact your bank or credit or debit card company to find out why the payment failed.","s":["If you entered your address correctly and the payment was rejected, you need to contact your bank or credit or debit card company to find out why the payment failed."]},{"k":"h","c":1,"t":"Card ID or CVV Mismatch"},{"k":"p","c":1,"t":"Card ID or Card Verification Value (CVV) is required when paying by credit card or debit card. It is a numerical code that is 3-digits (MasterCard, Visa, Discover) or 4-digits (American Express) long. Make sure you enter the correct code from your card.","s":["Card ID or Card Verification Value (CVV) is required when paying by credit card or debit card.","It is a numerical code that is 3-digits (MasterCard, Visa, Discover) or 4-digits (American Express) long.","Make sure you enter the correct code from your card."]},{"k":"p","c":1,"t":"If you enter an incorrect code, you’ll get an error message. If the payment is rejected, you won’t receive a payment confirmation. If this happens, try using another card or payment method.","s":["If you enter an incorrect code, you’ll get an error message.","If the payment is rejected, you won’t receive a payment confirmation.","If this happens, try using another card or payment method."]},{"k":"h","c":1,"t":"Duplicate Payments"},{"k":"p","c":1,"t":"You can get help if your card was charged more than once for the same violation.","s":["You can get help if your card was charged more than once for the same violation."]},{"k":"p","c":1,"t":"If you mistakenly overpaid, a refund will be automatically mailed to the registered owner of the vehicle 30 business days later. Overpayments are first applied to any outstanding judgment debt before any funds are returned to the payee.","s":["If you mistakenly overpaid, a refund will be automatically mailed to the registered owner of the vehicle 30 business days later.","Overpayments are first applied to any outstanding judgment debt before any funds are returned to the payee."]},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) for help.","s":["Call 311 or 212-NEW-YORK (212-639-9675) for help."]},{"k":"h","c":1,"t":"Foreign Addresses"},{"k":"p","c":1,"t":"You can pay a parking ticket or camera violation using a credit or debit card on the DOF website with a foreign address. In addition to the standard 2% convenience fee for credit or debit card payments, your bank might also charge you an additional fee to convert the funds into US dollars.","s":["You can pay a parking ticket or camera violation using a credit or debit card on the DOF website with a foreign address.","In addition to the standard 2% convenience fee for credit or debit card payments, your bank might also charge you an additional fee to convert the funds into US dollars."]},{"k":"p","c":1,"t":"If you receive an error that your zip code wasn’t accepted, you should type your entire foreign address, including county, province, borough, state, or district and your zip code in the Address and Address2 fields. In the Zip Code field, type \"00000\" (five zeroes).","s":["If you receive an error that your zip code wasn’t accepted, you should type your entire foreign address, including county, province, borough, state, or district and your zip code in the Address and Address2 fields.","In the Zip Code field, type \"00000\" (five zeroes)."]},{"k":"p","c":1,"t":"For an address in Canada, select the correct province in the State field. You should choose \"Canada\" in the Country field.","s":["For an address in Canada, select the correct province in the State field.","You should choose \"Canada\" in the Country field."]},{"k":"p","c":1,"t":"For all other countries, select \"FO-Foreign\" in the State field and the correct country in the Country field.","s":["For all other countries, select \"FO-Foreign\" in the State field and the correct country in the Country field."]},{"k":"p","c":1,"t":"If you continue to receive an error message, consider paying with e-check.","s":["If you continue to receive an error message, consider paying with e-check."]},{"k":"h","c":1,"t":"Holds"},{"k":"p","c":1,"t":"If a credit or debit card payment does not go through, your bank or credit union may still place a hold on your funds. Different banks and credit unions have different processes and timeframes for releasing holds.","s":["If a credit or debit card payment does not go through, your bank or credit union may still place a hold on your funds.","Different banks and credit unions have different processes and timeframes for releasing holds."]},{"k":"h","c":1,"t":"American Express: up to 3 days"},{"k":"p","c":1,"t":"Bank of America Visa or MasterCard: up to 5 days","s":["Bank of America Visa or MasterCard: up to 5 days"]},{"k":"h","c":1,"t":"Capital One Visa or MasterCard: up to 5 days"},{"k":"h","c":1,"t":"Chase Visa or MasterCard: up to 5 days"},{"k":"h","c":1,"t":"Citibank: up to 30 days"},{"k":"h","c":1,"t":"Discover: up to 10 days"},{"k":"p","c":1,"t":"HSBC: up to 3 days for its debit cards and 30 days for its credit cards","s":["HSBC: up to 3 days for its debit cards and 30 days for its credit cards"]},{"k":"h","c":1,"t":"TD Bank Visa or MasterCard: up to 5 days"},{"k":"h","c":1,"t":"Wells Fargo: 1 to 5 business days"},{"k":"h","c":1,"t":"Most credit unions: up to 30 days"},{"k":"p","c":1,"t":"If it can take your bank or credit union 10 or more days to release a hold, you can request assistance from the Department of Finance (DOF) after 10 days. If the bank or credit union takes fewer than 10 days to release a hold, you should wait until the hold is released before contacting DOF.","s":["If it can take your bank or credit union 10 or more days to release a hold, you can request assistance from the Department of Finance (DOF) after 10 days.","If the bank or credit union takes fewer than 10 days to release a hold, you should wait until the hold is released before contacting DOF."]},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) for help.","s":["Call 311 or 212-NEW-YORK (212-639-9675) for help."]},{"k":"h","c":0,"t":"Disputes"},{"k":"p","c":1,"t":"You can get help with parking ticket or camera violation disputes and hearings.","s":["You can get help with parking ticket or camera violation disputes and hearings."]},{"k":"h","c":1,"t":"Status"},{"k":"p","c":1,"t":"After your request is submitted, a hearing will be held within 14 to 45 days. You will be sent a copy of the administrative law judge's decision after the hearing. For in-person hearings, you get the decision at the conclusion of the hearing.","s":["After your request is submitted, a hearing will be held within 14 to 45 days.","You will be sent a copy of the administrative law judge's decision after the hearing.","For in-person hearings, you get the decision at the conclusion of the hearing."]},{"k":"p","c":1,"t":"If you requested a hearing online or by app, you will be emailed the decision about 2 weeks after the hearing to the email address you provided in your request. The email will be from NYCServ@finance.nyc.gov. If you don’t see the email, check your junk and/or spam folder. Please note this is an outgoing email address, any emails sent to this address will not be received or responded to.","s":["If you requested a hearing online or by app, you will be emailed the decision about 2 weeks after the hearing to the email address you provided in your request.","The email will be from NYCServ@finance.nyc.gov.","If you don’t see the email, check your junk and/or spam folder.","Please note this is an outgoing email address, any emails sent to this address will not be received or responded to."]},{"k":"p","c":1,"t":"If you requested a hearing by mail, the decision will be mailed about 10 days after the hearing to the address you provided with your defense or the address where the vehicle is registered.","s":["If you requested a hearing by mail, the decision will be mailed about 10 days after the hearing to the address you provided with your defense or the address where the vehicle is registered."]},{"k":"p","c":1,"t":"If it's been more than the normal timeframe and you haven't received a decision, you should check the status of your violation. If there's no information available in the system, you can request the status from the Department of Finance.","s":["If it's been more than the normal timeframe and you haven't received a decision, you should check the status of your violation.","If there's no information available in the system, you can request the status from the Department of Finance."]},{"k":"p","c":1,"t":"Look up your parking tickets or camera violations.","s":["Look up your parking tickets or camera violations."]},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) if you need more help.","s":["Call 311 or 212-NEW-YORK (212-639-9675) if you need more help."]},{"k":"h","c":1,"t":"Blocked Violation or Vehicle"},{"k":"p","c":1,"t":"If your plate or ticket is blocked and you cannot pay or request a hearing, contact or visit the Department of Finance for more information.","s":["If your plate or ticket is blocked and you cannot pay or request a hearing, contact or visit the Department of Finance for more information."]},{"k":"p","c":1,"t":"If you have three or more returned online payments on the parking and camera violations website within a 6-month period, you will be automatically blocked from using the online payment system.","s":["If you have three or more returned online payments on the parking and camera violations website within a 6-month period, you will be automatically blocked from using the online payment system."]},{"k":"p","c":1,"t":"If you are blocked and try to pay online, you will see a message on the screen that says \"This plate has been blocked from making payments online. You may pay in person or by mail. For more information on how to pay, go to www.nyc.gov/payonline or read payment instructions on your parking ticket.\"","s":["If you are blocked and try to pay online, you will see a message on the screen that says \"This plate has been blocked from making payments online.","You may pay in person or by mail.","For more information on how to pay, go to www.nyc.gov/payonline or read payment instructions on your parking ticket.\""]},{"k":"p","c":1,"t":"If your license plate is added to the list of blocked payments, you will get an email with details about your returned payment and instructions on how to be removed from the list. Once your debt on the license plate is cleared for 15 calendar days, you will be able to pay online again. If the behavior continues, you may be blocked from making online payments permanently.","s":["If your license plate is added to the list of blocked payments, you will get an email with details about your returned payment and instructions on how to be removed from the list.","Once your debt on the license plate is cleared for 15 calendar days, you will be able to pay online again.","If the behavior continues, you may be blocked from making online payments permanently."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"In Person"},{"k":"p","c":1,"t":"Visit a DOF Business Center.","s":["Visit a DOF Business Center."]},{"k":"h","c":1,"t":"Evidence Adjournment"},{"k":"p","c":1,"t":"After submitting your defense, you may receive a letter or email requesting additional evidence. You have 30 days from the adjournment date (which is listed in the middle of the page) to send in the requested evidence. Along with the evidence, include your ticket or NOL number and your license plate number and the state the vehicle is registered in.","s":["After submitting your defense, you may receive a letter or email requesting additional evidence.","You have 30 days from the adjournment date (which is listed in the middle of the page) to send in the requested evidence.","Along with the evidence, include your ticket or NOL number and your license plate number and the state the vehicle is registered in."]},{"k":"p","c":1,"t":"Mail to:","s":["Mail to:"]},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Hearing by Mail Unit"},{"k":"h","c":1,"t":"P.O. Box 29021"},{"k":"h","c":1,"t":"Brooklyn, NY 11202-9021"},{"k":"h","c":1,"t":"Evidence Submission Failure"},{"k":"p","c":1,"t":"If you received an “Evidence Upload Failure” message while disputing online or with the app, the evidence files you tried to attach weren’t submitted.","s":["If you received an “Evidence Upload Failure” message while disputing online or with the app, the evidence files you tried to attach weren’t submitted."]},{"k":"p","c":1,"t":"You may have exceeded the 20 MB limit. If you need to submit files that are over 10 MB, you should make your hearing request online, by mail, or in person.","s":["You may have exceeded the 20 MB limit.","If you need to submit files that are over 10 MB, you should make your hearing request online, by mail, or in person."]},{"k":"p","c":1,"t":"Another reason you can get this kind of error is if you’re trying to upload file types that aren’t accepted by the app.","s":["Another reason you can get this kind of error is if you’re trying to upload file types that aren’t accepted by the app."]},{"k":"p","c":1,"t":"The acceptable image and file formats are:","s":["The acceptable image and file formats are:"]},{"k":"h","c":1,"t":"JPEG/JPG"},{"k":"h","c":1,"t":"TIFF"},{"k":"h","c":1,"t":"BMP"},{"k":"h","c":1,"t":"Non-animated GIFs"},{"k":"p","c":1,"t":"If you requested a hearing and received confirmation but had a problem submitting evidence and still want to submit that evidence, you need to immediately request that your hearing be stopped. You should do this immediately, so it is stopped before the judge hears it.","s":["If you requested a hearing and received confirmation but had a problem submitting evidence and still want to submit that evidence, you need to immediately request that your hearing be stopped.","You should do this immediately, so it is stopped before the judge hears it."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Your message should include the violation number and a note that this is an \"Upload Problem.\" Don’t include evidence. DOF will email you instructions on how to send it.","s":["Your message should include the violation number and a note that this is an \"Upload Problem.\"","Don’t include evidence.","DOF will email you instructions on how to send it."]},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"In Person"},{"k":"p","c":1,"t":"Bring your ticket or Notice of Liability (NOL) and evidence to a DOF Business Center.","s":["Bring your ticket or Notice of Liability (NOL) and evidence to a DOF Business Center."]},{"k":"h","c":1,"t":"Notice of Unpaid Violation"},{"k":"p","c":1,"t":"Twenty days after a parking ticket is issued, DOF will send a Pre-Penalty Notice of Unpaid Violation to the DMV address on file for the registered owner of the vehicle. This letter reminds owners about an outstanding violation on a plate registered to them and gives instructions on how to pay or request a hearing.","s":["Twenty days after a parking ticket is issued, DOF will send a Pre-Penalty Notice of Unpaid Violation to the DMV address on file for the registered owner of the vehicle.","This letter reminds owners about an outstanding violation on a plate registered to them and gives instructions on how to pay or request a hearing."]},{"k":"p","c":1,"t":"If you received a notice that you still owe money on a violation that you already paid or had dismissed, it’s possible that DOF mailed the letter before they processed your payment or accepted your hearing request. Depending on how you paid, it may take up to two weeks for a payment to be posted. You may also still have a remaining balance on a ticket that you thought you paid in full or a penalty was added because you didn’t pay on time.","s":["If you received a notice that you still owe money on a violation that you already paid or had dismissed, it’s possible that DOF mailed the letter before they processed your payment or accepted your hearing request.","Depending on how you paid, it may take up to two weeks for a payment to be posted.","You may also still have a remaining balance on a ticket that you thought you paid in full or a penalty was added because you didn’t pay on time."]},{"k":"p","c":1,"t":"You should check the status of your violations to verify the information in the notice.","s":["You should check the status of your violations to verify the information in the notice."]},{"k":"p","c":1,"t":"If the ticket or Notice of Liability (NOL) number listed on the notice matches your payment or dispute records, you should send DOF proof of payment or dismissal and a copy of the notice.","s":["If the ticket or Notice of Liability (NOL) number listed on the notice matches your payment or dispute records, you should send DOF proof of payment or dismissal and a copy of the notice."]},{"k":"p","c":1,"t":"Proof of payment or dismissal may include:","s":["Proof of payment or dismissal may include:"]},{"k":"p","c":1,"t":"A copy of the front and back of a canceled check","s":["A copy of the front and back of a canceled check"]},{"k":"h","c":1,"t":"A copy of a cashed money order"},{"k":"h","c":1,"t":"A copy of a hearing decision or stamped printout"},{"k":"h","c":1,"t":"A copy of a credit card statement"},{"k":"h","c":1,"t":"The confirmation number for an online or phone payment"},{"k":"p","c":1,"t":"Look up your parking tickets or camera violations.","s":["Look up your parking tickets or camera violations."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"By Fax"},{"k":"h","c":1,"t":"(212) 232-1891"},{"k":"h","c":1,"t":"By Mail"},{"k":"p","c":1,"t":"For requests by mail, be sure to submit copies of the documents, not originals.","s":["For requests by mail, be sure to submit copies of the documents, not originals."]},{"k":"p","c":1,"t":"DOF will respond to requests by mail in about 15 days.","s":["DOF will respond to requests by mail in about 15 days."]},{"k":"p","c":1,"t":"Mail to:","s":["Mail to:"]},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Refunds Unit"},{"k":"h","c":1,"t":"59 Maiden Lane, 20th Floor"},{"k":"h","c":1,"t":"New York, NY 10038-4648"},{"k":"h","c":1,"t":"In Person"},{"k":"p","c":1,"t":"Visit a DOF Business Center.","s":["Visit a DOF Business Center."]},{"k":"p","c":1,"t":"You can contact the Parking Summons Advocate for help if you keep receiving notices from the Department of Finance or a collection agency about a ticket that you already paid or already had a hearing on but for which you never received a decision.","s":["You can contact the Parking Summons Advocate for help if you keep receiving notices from the Department of Finance or a collection agency about a ticket that you already paid or already had a hearing on but for which you never received a decision."]},{"k":"p","c":1,"t":"Learn more on the Parking Ticket or Camera Violation Advocate page.","s":["Learn more on the Parking Ticket or Camera Violation Advocate page."]},{"k":"h","c":1,"t":"Payment Made Before Hearing Requested"},{"k":"p","c":1,"t":"Since paying the violation is \"an admission of liability\" (meaning you admit you are guilty) do not pay the ticket if you want to request a hearing.","s":["Since paying the violation is \"an admission of liability\" (meaning you admit you are guilty) do not pay the ticket if you want to request a hearing."]},{"k":"p","c":1,"t":"If you mistakenly paid the ticket but still want to dispute the violation, you must do so by mail or in person within 30 days of the date of the ticket. Make sure to explain why you paid the violation.","s":["If you mistakenly paid the ticket but still want to dispute the violation, you must do so by mail or in person within 30 days of the date of the ticket.","Make sure to explain why you paid the violation."]},{"k":"h","c":1,"t":"Reinstatement of a Previously Dismissed Ticket"},{"k":"p","c":1,"t":"If fraud, misrepresentation, or misconduct was committed to obtain a dismissal of a parking ticket, the Department of Finance (DOF) may reinstate it.","s":["If fraud, misrepresentation, or misconduct was committed to obtain a dismissal of a parking ticket, the Department of Finance (DOF) may reinstate it."]},{"k":"p","c":1,"t":"If DOF determines that they shouldn’t have dismissed your ticket, you will be mailed a Notice of Hearing with a Statement in Support of Setting Aside Prior Dismissals.","s":["If DOF determines that they shouldn’t have dismissed your ticket, you will be mailed a Notice of Hearing with a Statement in Support of Setting Aside Prior Dismissals."]},{"k":"p","c":1,"t":"If you agree that you were guilty on the original ticket, you don’t have to appear at the hearing. You can call or send a letter to the DOF Fraud Investigation Unit to say you don’t object to the reinstatement and don’t plan to attend your hearing. DOF will submit the Reinstatement Petition and any evidence to a judge. You will get the judge’s decision by mail. The original ticket may be restored and you may have to pay up to three times the original fine and three times the additional penalties.","s":["If you agree that you were guilty on the original ticket, you don’t have to appear at the hearing.","You can call or send a letter to the DOF Fraud Investigation Unit to say you don’t object to the reinstatement and don’t plan to attend your hearing.","DOF will submit the Reinstatement Petition and any evidence to a judge.","You will get the judge’s decision by mail.","The original ticket may be restored and you may have to pay up to three times the original fine and three times the additional penalties."]},{"k":"p","c":1,"t":"If you want to dispute the reinstatement, you must participate in a hearing. A hearing will be scheduled where you will have a chance to dispute the reinstatement. You can appear by yourself, with an attorney, or send an eligible representative who is authorized, in writing, to speak on your behalf.","s":["If you want to dispute the reinstatement, you must participate in a hearing.","A hearing will be scheduled where you will have a chance to dispute the reinstatement.","You can appear by yourself, with an attorney, or send an eligible representative who is authorized, in writing, to speak on your behalf."]},{"k":"p","c":1,"t":"You can contact the DOF Fraud Investigation Unit by phone or by mail.","s":["You can contact the DOF Fraud Investigation Unit by phone or by mail."]},{"k":"h","c":1,"t":"By Phone"},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) for help.","s":["Call 311 or 212-NEW-YORK (212-639-9675) for help."]},{"k":"h","c":1,"t":"By Mail"},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Fraud Investigation Unit"},{"k":"h","c":1,"t":"Legal Affairs Division"},{"k":"h","c":1,"t":"375 Pearl Street, 30th Floor"},{"k":"h","c":1,"t":"New York, NY 10038"},{"k":"h","c":0,"t":"Enforcement and Collections"},{"k":"p","c":1,"t":"If you don’t pay your violations or have them dismissed, you will be subject to penalties, interest, booting and towing, and other enforcement actions.","s":["If you don’t pay your violations or have them dismissed, you will be subject to penalties, interest, booting and towing, and other enforcement actions."]},{"k":"p","c":1,"t":"To resolve your tickets, you can:","s":["To resolve your tickets, you can:"]},{"k":"h","c":1,"t":"Pay your violations"},{"k":"h","c":1,"t":"Request a hearing"},{"k":"h","c":1,"t":"Sign up for a payment plan"},{"k":"h","c":1,"t":"Apply for military service member debt relief"},{"k":"h","c":1,"t":"Penalties"},{"k":"p","c":1,"t":"You have 30 days from the date of the parking ticket or camera Notice of Liability (NOL) to pay the fine or request a hearing. After 30 days, penalties and interest will begin to be added. If the violations go into judgment, additional enforcement actions may be taken.","s":["You have 30 days from the date of the parking ticket or camera Notice of Liability (NOL) to pay the fine or request a hearing.","After 30 days, penalties and interest will begin to be added.","If the violations go into judgment, additional enforcement actions may be taken."]},{"k":"p","c":1,"t":"Twenty days after a parking ticket is issued or the date of the NOL, the Department of Finance (DOF) will send a Pre-Penalty Notice of Unpaid Violation to the address on file at the Department of Motor Vehicles (DMV) for the registered owner of the vehicle. This letter reminds owners about an outstanding violation on a plate registered to them and gives instructions on how to pay or request a hearing. Make sure to keep your address up to date with the DMV to ensure that you receive these notices in the future.","s":["Twenty days after a parking ticket is issued or the date of the NOL, the Department of Finance (DOF) will send a Pre-Penalty Notice of Unpaid Violation to the address on file at the Department of Motor Vehicles (DMV) for the registered owner of the vehicle.","This letter reminds owners about an outstanding violation on a plate registered to them and gives instructions on how to pay or request a hearing.","Make sure to keep your address up to date with the DMV to ensure that you receive these notices in the future."]},{"k":"h","c":1,"t":"Parking Tickets"},{"k":"p","c":1,"t":"After 30 days, an additional $10 is added to the fine amount.","s":["After 30 days, an additional $10 is added to the fine amount."]},{"k":"p","c":1,"t":"After 60 days, an additional $20 is added to the fine and first penalty.","s":["After 60 days, an additional $20 is added to the fine and first penalty."]},{"k":"p","c":1,"t":"After 90 days, an additional $30 is added to the fine and both penalties.","s":["After 90 days, an additional $30 is added to the fine and both penalties."]},{"k":"p","c":1,"t":"After about 100 days, the violation is entered into judgment and 9% simple interest per year is then added to the total amount due. Each month, one-twelfth of the 9% of the unpaid judgment is added to the amount due, until the outstanding amount is paid.","s":["After about 100 days, the violation is entered into judgment and 9% simple interest per year is then added to the total amount due.","Each month, one-twelfth of the 9% of the unpaid judgment is added to the amount due, until the outstanding amount is paid."]},{"k":"h","c":1,"t":"Camera Violations"},{"k":"p","c":1,"t":"After 30 days, a $25 penalty will be added.","s":["After 30 days, a $25 penalty will be added."]},{"k":"p","c":1,"t":"After 65 days, a Final Notice is mailed.","s":["After 65 days, a Final Notice is mailed."]},{"k":"p","c":1,"t":"After about 75 days, the violation is entered into judgment and 9% simple interest per year is then added to the total amount due. Each month, one-twelfth of the 9% of the unpaid judgment is added to the amount due, until the outstanding amount is paid.","s":["After about 75 days, the violation is entered into judgment and 9% simple interest per year is then added to the total amount due.","Each month, one-twelfth of the 9% of the unpaid judgment is added to the amount due, until the outstanding amount is paid."]},{"k":"h","c":1,"t":"Enforcement Actions"},{"k":"h","c":1,"t":"Booting and Towing"},{"k":"p","c":1,"t":"When the combined judgment debt owed for parking tickets and camera violations exceeds $350 for all vehicles registered to the same owner, any of those vehicles may be booted or towed. For example, if you own two vehicles and have an $80 bus lane camera violation in judgment on one car and $271 in parking violations in judgment on the other car, either car may be booted.","s":["When the combined judgment debt owed for parking tickets and camera violations exceeds $350 for all vehicles registered to the same owner, any of those vehicles may be booted or towed.","For example, if you own two vehicles and have an $80 bus lane camera violation in judgment on one car and $271 in parking violations in judgment on the other car, either car may be booted."]},{"k":"p","c":1,"t":"If your vehicle is booted, a booting fee and marshal or sheriff fees will be added to the judgment amount owed.","s":["If your vehicle is booted, a booting fee and marshal or sheriff fees will be added to the judgment amount owed."]},{"k":"p","c":1,"t":"If you don't resolve your judgment debt within 48 hours of being booted, or if your vehicle meets the criteria for an immediate tow, then a tow fee will be added. Vehicles that remain in the tow pound will be charged a storage fee after the first day they are brought into the pound.","s":["If you don't resolve your judgment debt within 48 hours of being booted, or if your vehicle meets the criteria for an immediate tow, then a tow fee will be added.","Vehicles that remain in the tow pound will be charged a storage fee after the first day they are brought into the pound."]},{"k":"p","c":1,"t":"If you don't pay the total amount owed, the vehicle will be auctioned. To learn more about booting and towing, visit the Booted Vehicle or Towed Vehicle page.","s":["If you don't pay the total amount owed, the vehicle will be auctioned.","To learn more about booting and towing, visit the Booted Vehicle or Towed Vehicle page."]},{"k":"h","c":1,"t":"Other Enforcement Actions"},{"k":"p","c":1,"t":"In addition to booting and towing, DOF may take other enforcement actions against the registered owner of the vehicle.","s":["In addition to booting and towing, DOF may take other enforcement actions against the registered owner of the vehicle."]},{"k":"p","c":1,"t":"DOF may:","s":["DOF may:"]},{"k":"h","c":1,"t":"Garnish your wages"},{"k":"h","c":1,"t":"Restrain your bank accounts"},{"k":"h","c":1,"t":"Defer or suspend your NY State vehicle registration"},{"k":"h","c":1,"t":"Place a lien against your real property"},{"k":"h","c":1,"t":"Refer your account to a collection agency"},{"k":"h","c":1,"t":"Collection Agencies"},{"k":"p","c":1,"t":"The Department of Finance (DOF) hires collection agencies to notify vehicle owners of outstanding parking and camera violation judgments owed to New York City.","s":["The Department of Finance (DOF) hires collection agencies to notify vehicle owners of outstanding parking and camera violation judgments owed to New York City."]},{"k":"p","c":1,"t":"You may receive a call or letter from the collection agency about your debt. When calling or sending letters, collection agency staff members must identify themselves as employees of a collection agency.","s":["You may receive a call or letter from the collection agency about your debt.","When calling or sending letters, collection agency staff members must identify themselves as employees of a collection agency."]},{"k":"p","c":1,"t":"Collection agencies that contract with DOF don’t accept payments directly. If you received a letter from a collection agency about violations, you can discuss the letter and debt with them, but any payments must be made to DOF.","s":["Collection agencies that contract with DOF don’t accept payments directly.","If you received a letter from a collection agency about violations, you can discuss the letter and debt with them, but any payments must be made to DOF."]},{"k":"p","c":1,"t":"If you have a question about your unpaid violations, you can write to:","s":["If you have a question about your unpaid violations, you can write to:"]},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Church Street Station"},{"k":"h","c":1,"t":"P.O. Box 3615"},{"k":"h","c":1,"t":"New York, NY 10008"},{"k":"p","c":1,"t":"You can make a complaint about a collection agency with DOF online or by mail","s":["You can make a complaint about a collection agency with DOF online or by mail"]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"By Mail"},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Collections Division"},{"k":"h","c":1,"t":"59 Maiden Lane, 24th Floor"},{"k":"h","c":1,"t":"New York, NY 10038"},{"k":"p","c":1,"t":"You can contact the Parking Summons Advocate for help if you keep receiving notices from the Department of Finance or a collection agency about a ticket that you already paid or already had a hearing on but for which you never received a decision.","s":["You can contact the Parking Summons Advocate for help if you keep receiving notices from the Department of Finance or a collection agency about a ticket that you already paid or already had a hearing on but for which you never received a decision."]},{"k":"p","c":1,"t":"Learn more on the Parking Ticket or Camera Violation Advocate page.","s":["Learn more on the Parking Ticket or Camera Violation Advocate page."]},{"k":"h","c":1,"t":"Vehicle Registration Deferment"},{"k":"p","c":1,"t":"Your New York State vehicle registration can be deferred or suspended if you have:","s":["Your New York State vehicle registration can be deferred or suspended if you have:"]},{"k":"p","c":1,"t":"3 or more outstanding parking, red light, bus lane or speed camera violations in any combination in judgment within an 18-month period, or","s":["3 or more outstanding parking, red light, bus lane or speed camera violations in any combination in judgment within an 18-month period, or"]},{"k":"p","c":1,"t":"5 or more outstanding parking violation judgments within a 12-month period","s":["5 or more outstanding parking violation judgments within a 12-month period"]},{"k":"p","c":1,"t":"Before you can register or renew your registration with the Department of Motor Vehicles (DMV), you must resolve all of your parking and camera violation judgment debt. To do this, you must pay what you owe or request a hearing to fight the violations, even if you are on a payment plan.","s":["Before you can register or renew your registration with the Department of Motor Vehicles (DMV), you must resolve all of your parking and camera violation judgment debt.","To do this, you must pay what you owe or request a hearing to fight the violations, even if you are on a payment plan."]},{"k":"p","c":1,"t":"After you resolve your violations, you need to request a Registration Clearance from the Department of Finance (DOF). Learn how to request a clearance on the Parking Ticket or Camera Violation Clearance page.","s":["After you resolve your violations, you need to request a Registration Clearance from the Department of Finance (DOF).","Learn how to request a clearance on the Parking Ticket or Camera Violation Clearance page."]},{"k":"h","c":0,"t":"Missing or Misapplied Payments"},{"k":"h","c":1,"t":"Missing Payment"},{"k":"p","c":1,"t":"You can get help if you made a payment and it’s not showing up in DOF’s system.","s":["You can get help if you made a payment and it’s not showing up in DOF’s system."]},{"k":"p","c":1,"t":"Payments aren't immediately reflected in DOF’s system. Depending on how you paid, it may take up to two weeks.","s":["Payments aren't immediately reflected in DOF’s system.","Depending on how you paid, it may take up to two weeks."]},{"k":"h","c":1,"t":"Payment Method"},{"k":"h","c":1,"t":"Post Date"},{"k":"h","c":1,"t":"Online"},{"k":"h","c":1,"t":"2 to 4 business days"},{"k":"h","c":1,"t":"Mobile App"},{"k":"h","c":1,"t":"2 to 4 business days"},{"k":"h","c":1,"t":"Mail"},{"k":"h","c":1,"t":"Up to 2 weeks"},{"k":"h","c":1,"t":"DOF Business Center"},{"k":"h","c":1,"t":"2 or more business days"},{"k":"p","c":1,"t":"If it’s been more than the normal processing time and the payment still isn’t showing up in the system, you can ask DOF to investigate.","s":["If it’s been more than the normal processing time and the payment still isn’t showing up in the system, you can ask DOF to investigate."]},{"k":"p","c":1,"t":"Your request should include:","s":["Your request should include:"]},{"k":"h","c":1,"t":"Full name"},{"k":"p","c":1,"t":"Current address (note whether the address is different than the one on the notice or your DMV registration)","s":["Current address (note whether the address is different than the one on the notice or your DMV registration)"]},{"k":"h","c":1,"t":"Plate number"},{"k":"h","c":1,"t":"State of registration"},{"k":"h","c":1,"t":"Ticket (or NOL) number(s) and date(s) issued"},{"k":"h","c":1,"t":"Copy of your proof of payment"},{"k":"h","c":1,"t":"Any relevant details about your violations or payments"},{"k":"p","c":1,"t":"Proof of payment may include:","s":["Proof of payment may include:"]},{"k":"p","c":1,"t":"A copy of the front and back of a canceled check","s":["A copy of the front and back of a canceled check"]},{"k":"h","c":1,"t":"A copy of a cashed money order"},{"k":"h","c":1,"t":"A copy of a credit card statement"},{"k":"h","c":1,"t":"The confirmation number for an online or phone payment"},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"By Phone"},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) for help.","s":["Call 311 or 212-NEW-YORK (212-639-9675) for help."]},{"k":"h","c":1,"t":"By Fax"},{"k":"h","c":1,"t":"(212) 232-1891"},{"k":"h","c":1,"t":"By Mail"},{"k":"p","c":1,"t":"For requests by mail, be sure to submit copies of the documents, not originals.","s":["For requests by mail, be sure to submit copies of the documents, not originals."]},{"k":"p","c":1,"t":"DOF will respond to requests by mail in about 15 days.","s":["DOF will respond to requests by mail in about 15 days."]},{"k":"p","c":1,"t":"Mail to:","s":["Mail to:"]},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Refunds Unit"},{"k":"h","c":1,"t":"59 Maiden Lane, 20th Floor"},{"k":"h","c":1,"t":"New York, NY 10038-4648"},{"k":"h","c":1,"t":"In Person"},{"k":"p","c":1,"t":"Visit a DOF Business Center.","s":["Visit a DOF Business Center."]},{"k":"h","c":1,"t":"Misapplied Payment"},{"k":"p","c":1,"t":"You can get help if you made a payment for the wrong violation. You can also request reimbursement for credit or debit card payments that haven’t been applied to a ticket.","s":["You can get help if you made a payment for the wrong violation.","You can also request reimbursement for credit or debit card payments that haven’t been applied to a ticket."]},{"k":"p","c":1,"t":"Your request should include:","s":["Your request should include:"]},{"k":"h","c":1,"t":"Full name"},{"k":"p","c":1,"t":"Current address (note whether the address is different than the one on the notice or your DMV registration)","s":["Current address (note whether the address is different than the one on the notice or your DMV registration)"]},{"k":"h","c":1,"t":"Plate number"},{"k":"h","c":1,"t":"State of registration"},{"k":"h","c":1,"t":"Ticket (or NOL) number(s) and date(s) issued"},{"k":"h","c":1,"t":"Copy of your proof of payment"},{"k":"h","c":1,"t":"Any relevant details about your violations or payments"},{"k":"p","c":1,"t":"Proof of payment may include:","s":["Proof of payment may include:"]},{"k":"p","c":1,"t":"A copy of the front and back of a canceled check","s":["A copy of the front and back of a canceled check"]},{"k":"h","c":1,"t":"A copy of a cashed money order"},{"k":"h","c":1,"t":"A copy of a credit card statement"},{"k":"h","c":1,"t":"The confirmation number for an online or phone payment"},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"By Phone"},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) for help.","s":["Call 311 or 212-NEW-YORK (212-639-9675) for help."]},{"k":"h","c":1,"t":"By Fax"},{"k":"h","c":1,"t":"(212) 232-1891"},{"k":"h","c":1,"t":"By Mail"},{"k":"p","c":1,"t":"For requests by mail, be sure to submit copies of the documents, not originals.","s":["For requests by mail, be sure to submit copies of the documents, not originals."]},{"k":"p","c":1,"t":"DOF will respond to requests by mail in about 15 days.","s":["DOF will respond to requests by mail in about 15 days."]},{"k":"p","c":1,"t":"Mail to:","s":["Mail to:"]},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Refunds Unit"},{"k":"h","c":1,"t":"59 Maiden Lane, 20th Floor"},{"k":"h","c":1,"t":"New York, NY 10038-4648"},{"k":"h","c":1,"t":"In Person"},{"k":"p","c":1,"t":"Visit a DOF Business Center.","s":["Visit a DOF Business Center."]},{"k":"h","c":0,"t":"Mobile App Payments and Disputes"},{"k":"p","c":1,"t":"You can get help if you encountered an issue with paying or disputing with the NYC Parking Ticket Pay or Dispute App.","s":["You can get help if you encountered an issue with paying or disputing with the NYC Parking Ticket Pay or Dispute App."]},{"k":"p","c":1,"t":"If you receive an error message while trying to pay or fight a ticket, make sure to follow the instructions provided or try again. If the problem persists, consider paying or fighting your ticket online, by mail, or at a DOF Business Center.","s":["If you receive an error message while trying to pay or fight a ticket, make sure to follow the instructions provided or try again.","If the problem persists, consider paying or fighting your ticket online, by mail, or at a DOF Business Center."]},{"k":"h","c":1,"t":"Blocked Violation or Vehicle"},{"k":"p","c":1,"t":"If your plate or ticket is blocked and you cannot pay or request a hearing, contact or visit the Department of Finance for more information.","s":["If your plate or ticket is blocked and you cannot pay or request a hearing, contact or visit the Department of Finance for more information."]},{"k":"p","c":1,"t":"If you have three or more returned online payments on the parking and camera violations website within a 6-month period, you will be automatically blocked from using the online payment system.","s":["If you have three or more returned online payments on the parking and camera violations website within a 6-month period, you will be automatically blocked from using the online payment system."]},{"k":"p","c":1,"t":"If you are blocked and try to pay online, you will see a message on the screen that says \"This plate has been blocked from making payments online. You may pay in person or by mail. For more information on how to pay, go to www.nyc.gov/payonline or read payment instructions on your parking ticket.\"","s":["If you are blocked and try to pay online, you will see a message on the screen that says \"This plate has been blocked from making payments online.","You may pay in person or by mail.","For more information on how to pay, go to www.nyc.gov/payonline or read payment instructions on your parking ticket.\""]},{"k":"p","c":1,"t":"If your license plate is added to the list of blocked payments, you will get an email with details about your returned payment and instructions on how to be removed from the list. Once your debt on the license plate is cleared for 15 calendar days, you will be able to pay online again. If the behavior continues, you may be blocked from making online payments permanently.","s":["If your license plate is added to the list of blocked payments, you will get an email with details about your returned payment and instructions on how to be removed from the list.","Once your debt on the license plate is cleared for 15 calendar days, you will be able to pay online again.","If the behavior continues, you may be blocked from making online payments permanently."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"In Person"},{"k":"p","c":1,"t":"Visit a DOF Business Center.","s":["Visit a DOF Business Center."]},{"k":"h","c":1,"t":"Bugs and Technical Issues"},{"k":"p","c":1,"t":"You can report bugs and other technical issues with the NYC Parking Ticket Pay or Dispute App by tapping the \"Contact Us\" link within the app's Help section.","s":["You can report bugs and other technical issues with the NYC Parking Ticket Pay or Dispute App by tapping the \"Contact Us\" link within the app's Help section."]},{"k":"h","c":1,"t":"Camera Access Issues"},{"k":"p","c":1,"t":"If you get a “Unable to Access the Camera” error, you haven’t given the app permission to use your phone's camera. You can’t take a picture using the app without this permission. If you have problems uploading evidence, try closing the app completely, reopening, and uploading again. If you’re unable to resolve the errors, you should fight your violation using a different dispute method.","s":["If you get a “Unable to Access the Camera” error, you haven’t given the app permission to use your phone's camera.","You can’t take a picture using the app without this permission.","If you have problems uploading evidence, try closing the app completely, reopening, and uploading again.","If you’re unable to resolve the errors, you should fight your violation using a different dispute method."]},{"k":"h","c":1,"t":"Duplicate Payments"},{"k":"p","c":1,"t":"If you received a “Duplicate Payment Request” error, the system detected an additional payment request for the same violations. If you didn’t make a previous payment request, you should contact DOF for assistance.","s":["If you received a “Duplicate Payment Request” error, the system detected an additional payment request for the same violations.","If you didn’t make a previous payment request, you should contact DOF for assistance."]},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"Invalid Data Entered"},{"k":"p","c":1,"t":"If you received an “Invalid Ticket Number” error, the number you entered doesn’t have 10 digits or isn’t in the correct format. If you received an “Invalid Name/Address/Zip/Country” error, the information you entered isn’t in an acceptable format. Carefully complete all required fields to continue. You won't receive this error if the ticket isn't in the system yet.","s":["If you received an “Invalid Ticket Number” error, the number you entered doesn’t have 10 digits or isn’t in the correct format.","If you received an “Invalid Name/Address/Zip/Country” error, the information you entered isn’t in an acceptable format.","Carefully complete all required fields to continue.","You won't receive this error if the ticket isn't in the system yet."]},{"k":"h","c":1,"t":"Submission Errors"},{"k":"p","c":1,"t":"If you get a “Error Occurred While Submitting Your Request” or “Unable to Process Your Request at This Time” error, your request was not submitted. You should try again later or use another payment or dispute method.","s":["If you get a “Error Occurred While Submitting Your Request” or “Unable to Process Your Request at This Time” error, your request was not submitted.","You should try again later or use another payment or dispute method."]},{"k":"p","c":1,"t":"If you get a “Server Unresponsive” error, your request wasn’t submitted because the application is having a planned or unplanned outage or a problem processing payments and hearing requests. You should try again later or use another payment or dispute method.","s":["If you get a “Server Unresponsive” error, your request wasn’t submitted because the application is having a planned or unplanned outage or a problem processing payments and hearing requests.","You should try again later or use another payment or dispute method."]},{"k":"h","c":1,"t":"Evidence Submission Issues"},{"k":"p","c":1,"t":"If you received an “Evidence Upload Failure” message while paying or disputing online or with the app, the evidence files you tried to attach weren’t submitted.","s":["If you received an “Evidence Upload Failure” message while paying or disputing online or with the app, the evidence files you tried to attach weren’t submitted."]},{"k":"p","c":1,"t":"You may have exceeded the 20 MB limit. If you need to submit files that are over 20 MB, you should make your hearing request online, by mail, or in person.","s":["You may have exceeded the 20 MB limit.","If you need to submit files that are over 20 MB, you should make your hearing request online, by mail, or in person."]},{"k":"p","c":1,"t":"Another reason you can get this kind of error is if you’re trying to upload file types that aren’t accepted.","s":["Another reason you can get this kind of error is if you’re trying to upload file types that aren’t accepted."]},{"k":"p","c":1,"t":"The acceptable image and file formats are:","s":["The acceptable image and file formats are:"]},{"k":"h","c":1,"t":"JPEG/JPG"},{"k":"h","c":1,"t":"TIFF"},{"k":"h","c":1,"t":"BMP"},{"k":"h","c":1,"t":"Non-animated GIFs"},{"k":"p","c":1,"t":"If you requested a hearing and received confirmation but had a problem submitting evidence and still want to submit that evidence, you need to immediately request that your hearing be stopped. You should do this immediately, so it is stopped before the judge hears it.","s":["If you requested a hearing and received confirmation but had a problem submitting evidence and still want to submit that evidence, you need to immediately request that your hearing be stopped.","You should do this immediately, so it is stopped before the judge hears it."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Your message should include the violation number and a note that this is an \"Upload Problem.\" Don’t include evidence. DOF will email you instructions on how to send it.","s":["Your message should include the violation number and a note that this is an \"Upload Problem.\"","Don’t include evidence.","DOF will email you instructions on how to send it."]},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"In Person"},{"k":"p","c":1,"t":"Bring your ticket or Notice of Liability (NOL) and evidence to a DOF Business Center.","s":["Bring your ticket or Notice of Liability (NOL) and evidence to a DOF Business Center."]},{"k":"h","c":0,"t":"Notices and Emails"},{"k":"p","c":1,"t":"After a parking ticket or camera violation is issued, the Department of Finance (DOF) requests the registered owner's information, including their address, from the State Department of Motor Vehicles (DMV). Notices of any unpaid fines, penalties, hearings, and judgments are mailed to the address on file. Make sure to keep your address up to date with the DMV to ensure that you receive these notices.","s":["After a parking ticket or camera violation is issued, the Department of Finance (DOF) requests the registered owner's information, including their address, from the State Department of Motor Vehicles (DMV).","Notices of any unpaid fines, penalties, hearings, and judgments are mailed to the address on file.","Make sure to keep your address up to date with the DMV to ensure that you receive these notices."]},{"k":"p","c":1,"t":"To learn how to change your name or address with the NY State DMV, go to the Vehicle Registration or License Plate page. If your vehicle is registered with a DMV from another state, check their website for their procedures.","s":["To learn how to change your name or address with the NY State DMV, go to the Vehicle Registration or License Plate page.","If your vehicle is registered with a DMV from another state, check their website for their procedures."]},{"k":"h","c":1,"t":"Boot or Tow Warning Email"},{"k":"p","c":1,"t":"You may receive a courtesy email from DOF if you have previously paid a ticket for a vehicle with nearly $350 in unpaid parking or camera summons judgment debt.","s":["You may receive a courtesy email from DOF if you have previously paid a ticket for a vehicle with nearly $350 in unpaid parking or camera summons judgment debt."]},{"k":"p","c":1,"t":"The email warns you to take action to avoid having your vehicle booted or towed by paying or disputing the tickets that are in judgment. The email lists the license plate of the vehicle with the judgment debt, but any vehicles registered to the same owner are subject to booting or towing, even if they aren't listed on the email or don't have any judgment debt.","s":["The email warns you to take action to avoid having your vehicle booted or towed by paying or disputing the tickets that are in judgment.","The email lists the license plate of the vehicle with the judgment debt, but any vehicles registered to the same owner are subject to booting or towing, even if they aren't listed on the email or don't have any judgment debt."]},{"k":"h","c":1,"t":"Confirmation Email"},{"k":"p","c":1,"t":"After an online or app transaction has been completed, you'll receive a confirmation page. You can capture a screenshot and keep that for your records. You’ll also get a confirmation email within one hour If you've provided a valid email address. If you’re using the app, you can choose to get a confirmation by text message.","s":["After an online or app transaction has been completed, you'll receive a confirmation page.","You can capture a screenshot and keep that for your records.","You’ll also get a confirmation email within one hour If you've provided a valid email address.","If you’re using the app, you can choose to get a confirmation by text message."]},{"k":"p","c":1,"t":"If your payment didn't go through, you won't get a confirmation. Instead you'll see a message that says \"Unable to process payment. Declined.\" The confirmation email includes:","s":["If your payment didn't go through, you won't get a confirmation.","Instead you'll see a message that says \"Unable to process payment.","Declined.\"","The confirmation email includes:"]},{"k":"h","c":1,"t":"Your receipt number"},{"k":"h","c":1,"t":"Transaction date and time"},{"k":"h","c":1,"t":"The total amount you paid"},{"k":"h","c":1,"t":"Ticket numbers, issue dates, and amounts"},{"k":"h","c":1,"t":"Provisional credit statement"},{"k":"p","c":1,"t":"Keep this email for future reference. If you don't see the email, check your Junk or Spam folder. The email will come from an email address ending in @finance.nyc.gov.","s":["Keep this email for future reference.","If you don't see the email, check your Junk or Spam folder.","The email will come from an email address ending in @finance.nyc.gov."]},{"k":"h","c":1,"t":"Evidence Adjournment"},{"k":"p","c":1,"t":"After submitting your defense, you may receive a letter or email requesting additional evidence. You have 30 days from the adjournment date (which is listed in the middle of the page) to send in the requested evidence. Along with the evidence, include your ticket or NOL number and your license plate number and the state the vehicle is registered in.","s":["After submitting your defense, you may receive a letter or email requesting additional evidence.","You have 30 days from the adjournment date (which is listed in the middle of the page) to send in the requested evidence.","Along with the evidence, include your ticket or NOL number and your license plate number and the state the vehicle is registered in."]},{"k":"p","c":1,"t":"Mail to:","s":["Mail to:"]},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Hearing by Mail Unit"},{"k":"h","c":1,"t":"P.O. Box 29021"},{"k":"h","c":1,"t":"Brooklyn, NY 11202-9021"},{"k":"h","c":1,"t":"Notice of Unpaid Violation"},{"k":"p","c":1,"t":"Twenty days after a parking ticket is issued, DOF will send a Pre-Penalty Notice of Unpaid Violation to the DMV address on file for the registered owner of the vehicle. This letter reminds owners about an outstanding violation on a plate registered to them and gives instructions on how to pay or request a hearing.","s":["Twenty days after a parking ticket is issued, DOF will send a Pre-Penalty Notice of Unpaid Violation to the DMV address on file for the registered owner of the vehicle.","This letter reminds owners about an outstanding violation on a plate registered to them and gives instructions on how to pay or request a hearing."]},{"k":"p","c":1,"t":"If you received a notice that you still owe money on a violation that you already paid or had dismissed, it’s possible that DOF mailed the letter before they processed your payment or accepted your hearing request. Depending on how you paid, it may take up to two weeks for a payment to be posted. You may also still have a remaining balance on a ticket that you thought you paid in full or a penalty was added because you didn’t pay on time.","s":["If you received a notice that you still owe money on a violation that you already paid or had dismissed, it’s possible that DOF mailed the letter before they processed your payment or accepted your hearing request.","Depending on how you paid, it may take up to two weeks for a payment to be posted.","You may also still have a remaining balance on a ticket that you thought you paid in full or a penalty was added because you didn’t pay on time."]},{"k":"p","c":1,"t":"You should check the status of your violations to verify the information in the notice.","s":["You should check the status of your violations to verify the information in the notice."]},{"k":"p","c":1,"t":"If the ticket or Notice of Liability (NOL) number listed on the notice matches your payment or dispute records, you should send DOF proof of payment or dismissal and a copy of the notice.","s":["If the ticket or Notice of Liability (NOL) number listed on the notice matches your payment or dispute records, you should send DOF proof of payment or dismissal and a copy of the notice."]},{"k":"p","c":1,"t":"Proof of payment or dismissal may include:","s":["Proof of payment or dismissal may include:"]},{"k":"p","c":1,"t":"A copy of the front and back of a canceled check","s":["A copy of the front and back of a canceled check"]},{"k":"h","c":1,"t":"A copy of a cashed money order"},{"k":"h","c":1,"t":"A copy of a hearing decision or stamped printout"},{"k":"h","c":1,"t":"A copy of a credit card statement"},{"k":"h","c":1,"t":"The confirmation number for an online or phone payment"},{"k":"p","c":1,"t":"Look up your parking tickets or camera violations.","s":["Look up your parking tickets or camera violations."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"By Fax"},{"k":"h","c":1,"t":"(212) 232-1891"},{"k":"h","c":1,"t":"By Mail"},{"k":"p","c":1,"t":"For requests by mail, be sure to submit copies of the documents, not originals.","s":["For requests by mail, be sure to submit copies of the documents, not originals."]},{"k":"p","c":1,"t":"DOF will respond to requests by mail in about 15 days.","s":["DOF will respond to requests by mail in about 15 days."]},{"k":"p","c":1,"t":"Mail to:","s":["Mail to:"]},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Refunds Unit"},{"k":"h","c":1,"t":"59 Maiden Lane, 20th Floor"},{"k":"h","c":1,"t":"New York, NY 10038-4648"},{"k":"h","c":1,"t":"In Person"},{"k":"p","c":1,"t":"Visit a DOF Business Center.","s":["Visit a DOF Business Center."]},{"k":"p","c":1,"t":"You can contact the Parking Summons Advocate for help if you keep receiving notices from the Department of Finance or a collection agency about a ticket that you already paid or already had a hearing on but for which you never received a decision.","s":["You can contact the Parking Summons Advocate for help if you keep receiving notices from the Department of Finance or a collection agency about a ticket that you already paid or already had a hearing on but for which you never received a decision."]},{"k":"p","c":1,"t":"Learn more on the Parking Ticket or Camera Violation Advocate page.","s":["Learn more on the Parking Ticket or Camera Violation Advocate page."]},{"k":"h","c":0,"t":"Online Payments and Disputes"},{"k":"p","c":1,"t":"You can get help if you encountered an issue with paying or disputing a violation online with CityPay.","s":["You can get help if you encountered an issue with paying or disputing a violation online with CityPay."]},{"k":"p","c":1,"t":"If you receive an error message while trying to pay or fight a ticket, make sure to follow the instructions provided or try again. If the problem persists, consider paying or fighting your ticket using a different method.","s":["If you receive an error message while trying to pay or fight a ticket, make sure to follow the instructions provided or try again.","If the problem persists, consider paying or fighting your ticket using a different method."]},{"k":"h","c":1,"t":"Blocked Violation or Vehicle"},{"k":"p","c":1,"t":"If your plate or ticket is blocked and you cannot pay or request a hearing, contact or visit the Department of Finance for more information.","s":["If your plate or ticket is blocked and you cannot pay or request a hearing, contact or visit the Department of Finance for more information."]},{"k":"p","c":1,"t":"If you have three or more returned online payments on the parking and camera violations website within a 6-month period, you will be automatically blocked from using the online payment system.","s":["If you have three or more returned online payments on the parking and camera violations website within a 6-month period, you will be automatically blocked from using the online payment system."]},{"k":"p","c":1,"t":"If you are blocked and try to pay online, you will see a message on the screen that says \"This plate has been blocked from making payments online. You may pay in person or by mail. For more information on how to pay, go to www.nyc.gov/payonline or read payment instructions on your parking ticket.\"","s":["If you are blocked and try to pay online, you will see a message on the screen that says \"This plate has been blocked from making payments online.","You may pay in person or by mail.","For more information on how to pay, go to www.nyc.gov/payonline or read payment instructions on your parking ticket.\""]},{"k":"p","c":1,"t":"If your license plate is added to the list of blocked payments, you will get an email with details about your returned payment and instructions on how to be removed from the list. Once your debt on the license plate is cleared for 15 calendar days, you will be able to pay online again. If the behavior continues, you may be blocked from making online payments permanently.","s":["If your license plate is added to the list of blocked payments, you will get an email with details about your returned payment and instructions on how to be removed from the list.","Once your debt on the license plate is cleared for 15 calendar days, you will be able to pay online again.","If the behavior continues, you may be blocked from making online payments permanently."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"In Person"},{"k":"p","c":1,"t":"Visit a DOF Business Center.","s":["Visit a DOF Business Center."]},{"k":"h","c":1,"t":"Browser Issues"},{"k":"p","c":1,"t":"Using Firefox to pay parking or camera violations online isn’t recommended because you may not be able to input all of the requested information. If you’re having an issue using Firefox, try using another browser, such as Chrome.","s":["Using Firefox to pay parking or camera violations online isn’t recommended because you may not be able to input all of the requested information.","If you’re having an issue using Firefox, try using another browser, such as Chrome."]},{"k":"h","c":1,"t":"Evidence Submission Issues"},{"k":"p","c":1,"t":"Don’t submit any links in your online hearing defense. If you submit a link, the judge won’t open it and view any evidence contained in the link. If the information in the link is important to your defense, you should print it out and either scan it for an online hearing or submit it for a hearing by mail.","s":["Don’t submit any links in your online hearing defense.","If you submit a link, the judge won’t open it and view any evidence contained in the link.","If the information in the link is important to your defense, you should print it out and either scan it for an online hearing or submit it for a hearing by mail."]},{"k":"p","c":1,"t":"Videos, including animated GIFs, aren’t accepted with an online hearing request. If you have a video as part of your evidence, you must have a hearing at a DOF Business Center. You must bring a device with you to play the video on, such as your mobile phone or camera. The judge will not be able to open a disk or flash drive.","s":["Videos, including animated GIFs, aren’t accepted with an online hearing request.","If you have a video as part of your evidence, you must have a hearing at a DOF Business Center.","You must bring a device with you to play the video on, such as your mobile phone or camera.","The judge will not be able to open a disk or flash drive."]},{"k":"p","c":1,"t":"If you requested a hearing and received confirmation but had a problem submitting evidence and still want to submit that evidence, you need to immediately request that your hearing be stopped. You should do this immediately, so it is stopped before the judge hears it.","s":["If you requested a hearing and received confirmation but had a problem submitting evidence and still want to submit that evidence, you need to immediately request that your hearing be stopped.","You should do this immediately, so it is stopped before the judge hears it."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Your message should include the violation number and a note that this is an \"Upload Problem.\" Don’t include evidence. DOF will email you instructions on how to send it.","s":["Your message should include the violation number and a note that this is an \"Upload Problem.\"","Don’t include evidence.","DOF will email you instructions on how to send it."]},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"In Person"},{"k":"p","c":1,"t":"Bring your ticket or Notice of Liability (NOL) and evidence to a DOF Business Center.","s":["Bring your ticket or Notice of Liability (NOL) and evidence to a DOF Business Center."]},{"k":"h","c":0,"t":"Penalty Adjustment"},{"k":"p","c":1,"t":"If you missed the payment's deadlines, fines, penalties and interest will not be waived. Most parking ticket or camera violation late penalties cannot be removed without proof of on-time payment.","s":["If you missed the payment's deadlines, fines, penalties and interest will not be waived.","Most parking ticket or camera violation late penalties cannot be removed without proof of on-time payment."]},{"k":"p","c":1,"t":"You can get help with parking ticket and camera violation penalties, including:","s":["You can get help with parking ticket and camera violation penalties, including:"]},{"k":"h","c":1,"t":"Payments and penalty notices that crossed in the mail"},{"k":"p","c":1,"t":"Penalty adjustment requests based on a claim that a parking hearing decision was never received","s":["Penalty adjustment requests based on a claim that a parking hearing decision was never received"]},{"k":"p","c":1,"t":"You can contact the Department of Finance to explain why you believe the penalty should be removed or reduced or to get help with any other questions about how much you owe.","s":["You can contact the Department of Finance to explain why you believe the penalty should be removed or reduced or to get help with any other questions about how much you owe."]},{"k":"p","c":1,"t":"Note that contacting DOF doesn't prevent additional penalties from increasing.","s":["Note that contacting DOF doesn't prevent additional penalties from increasing."]},{"k":"p","c":1,"t":"Your request should include:","s":["Your request should include:"]},{"k":"h","c":1,"t":"Full name"},{"k":"p","c":1,"t":"Current address (note whether the address is different than the one on the notice or your DMV registration)","s":["Current address (note whether the address is different than the one on the notice or your DMV registration)"]},{"k":"h","c":1,"t":"Plate number"},{"k":"h","c":1,"t":"State of registration"},{"k":"h","c":1,"t":"Ticket (or NOL) number(s) and date(s) issued"},{"k":"h","c":1,"t":"Copy of your proof of on-time payment"},{"k":"h","c":1,"t":"Any relevant details about your violations or payments"},{"k":"p","c":1,"t":"Proof of payment may include:","s":["Proof of payment may include:"]},{"k":"p","c":1,"t":"A copy of the front and back of a canceled check","s":["A copy of the front and back of a canceled check"]},{"k":"h","c":1,"t":"A copy of a cashed money order"},{"k":"h","c":1,"t":"A copy of a credit card statement"},{"k":"h","c":1,"t":"The confirmation number for an online or phone payment"},{"k":"p","c":1,"t":"DOF will review your case and decide if a penalty waiver is warranted. You will get a response by email within 7 days.","s":["DOF will review your case and decide if a penalty waiver is warranted.","You will get a response by email within 7 days."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Contact the Department of Finance.","s":["Contact the Department of Finance."]},{"k":"h","c":1,"t":"By Phone"},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) for help.","s":["Call 311 or 212-NEW-YORK (212-639-9675) for help."]},{"k":"h","c":1,"t":"Status"},{"k":"p","c":1,"t":"You can get help with the status of a payment or penalty adjustment.","s":["You can get help with the status of a payment or penalty adjustment."]},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) for help.","s":["Call 311 or 212-NEW-YORK (212-639-9675) for help."]},{"k":"h","c":0,"t":"Refunds"},{"k":"p","c":1,"t":"If you overpaid a parking ticket or camera violation, a refund is automatically mailed to the registered owner of the vehicle 30 business days later if:","s":["If you overpaid a parking ticket or camera violation, a refund is automatically mailed to the registered owner of the vehicle 30 business days later if:"]},{"k":"p","c":1,"t":"The amount you owed was reduced by a hearing or appeal after you paid","s":["The amount you owed was reduced by a hearing or appeal after you paid"]},{"k":"h","c":1,"t":"You paid the same ticket more than once"},{"k":"p","c":1,"t":"The violation that you paid wasn’t a NYC parking or camera violation","s":["The violation that you paid wasn’t a NYC parking or camera violation"]},{"k":"h","c":1,"t":"Your vehicle was booted or towed by mistake"},{"k":"p","c":1,"t":"Violations were dismissed after the boot was removed or you got your towed vehicle back","s":["Violations were dismissed after the boot was removed or you got your towed vehicle back"]},{"k":"h","c":1,"t":"You paid more than you owed"},{"k":"p","c":1,"t":"Overpayments are first applied to any outstanding judgment debt before any funds are returned to the payee.","s":["Overpayments are first applied to any outstanding judgment debt before any funds are returned to the payee."]},{"k":"p","c":1,"t":"No request is required, but if someone other than the registered vehicle owner paid and is requesting the refund, they must submit a Parking and Camera Violations Refund Form.","s":["No request is required, but if someone other than the registered vehicle owner paid and is requesting the refund, they must submit a Parking and Camera Violations Refund Form."]},{"k":"p","c":1,"t":"If your vehicle was towed by NYPD you have 30 days from the date of the violation to request a hearing. If the ticket that led to your vehicle being towed is dismissed you can request a refund of the tow fees. Booting and towing refunds are not generated automatically and require submission of a refund form. You must include a copy of your receipt or payment voucher.","s":["If your vehicle was towed by NYPD you have 30 days from the date of the violation to request a hearing.","If the ticket that led to your vehicle being towed is dismissed you can request a refund of the tow fees.","Booting and towing refunds are not generated automatically and require submission of a refund form.","You must include a copy of your receipt or payment voucher."]},{"k":"p","c":1,"t":"If you need to request a refund, you can do it online or by mail. If you have proof to submit, send copies of it along with your form by mail.","s":["If you need to request a refund, you can do it online or by mail.","If you have proof to submit, send copies of it along with your form by mail."]},{"k":"p","c":1,"t":"The Department of Finance usually takes about three weeks to process a submitted form.","s":["The Department of Finance usually takes about three weeks to process a submitted form."]},{"k":"h","c":1,"t":"Online"},{"k":"p","c":1,"t":"Request a parking ticket or camera violation refund.","s":["Request a parking ticket or camera violation refund."]},{"k":"h","c":1,"t":"By Mail"},{"k":"p","c":1,"t":"You can get the form online or request one by mail.","s":["You can get the form online or request one by mail."]},{"k":"p","c":1,"t":"Download the Parking Ticket and Camera Violation Refund Form.","s":["Download the Parking Ticket and Camera Violation Refund Form."]},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) to request a copy.","s":["Call 311 or 212-NEW-YORK (212-639-9675) to request a copy."]},{"k":"h","c":1,"t":"Refund Status"},{"k":"p","c":1,"t":"The Department of Finance usually takes about three weeks to process a submitted form.","s":["The Department of Finance usually takes about three weeks to process a submitted form."]},{"k":"p","c":1,"t":"Call 311 or 212-NEW-YORK (212-639-9675) for status.","s":["Call 311 or 212-NEW-YORK (212-639-9675) for status."]},{"k":"h","c":1,"t":"Stop Payments and Uncashed Refund Checks"},{"k":"p","c":1,"t":"You may not be able to cash a refund check if an overpayment bounced after Department of Finance (DOF) already sent out a refund check for the overpayment. If that happens, DOF will put a stop payment on the refund check if you haven’t cashed it yet.","s":["You may not be able to cash a refund check if an overpayment bounced after Department of Finance (DOF) already sent out a refund check for the overpayment.","If that happens, DOF will put a stop payment on the refund check if you haven’t cashed it yet."]},{"k":"p","c":1,"t":"DOF also puts stop payments on uncashed refund checks that are older than 6 months.","s":["DOF also puts stop payments on uncashed refund checks that are older than 6 months."]},{"k":"p","c":1,"t":"If your refund check can’t be cashed but you think the money is owed to you, mail DOF a letter that includes your:","s":["If your refund check can’t be cashed but you think the money is owed to you, mail DOF a letter that includes your:"]},{"k":"h","c":1,"t":"Name"},{"k":"h","c":1,"t":"Address (especially if you have moved)"},{"k":"h","c":1,"t":"License plate or ticket number"},{"k":"p","c":1,"t":"An explanation of why you think the check should be replaced","s":["An explanation of why you think the check should be replaced"]},{"k":"p","c":1,"t":"Requests are normally processed within 15 days.","s":["Requests are normally processed within 15 days."]},{"k":"p","c":1,"t":"Mail to:","s":["Mail to:"]},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Refunds Unit"},{"k":"h","c":1,"t":"59 Maiden Lane, 20th Floor"},{"k":"h","c":1,"t":"New York, NY 10038-4648"},{"k":"h","c":1,"t":"Unauthorized Credit Card Use"},{"k":"p","c":1,"t":"Sometimes criminals will make fraudulent charges using unauthorized credit cards. If you receive a charge that you did not authorize, you should contact your credit card issuer or bank to dispute the charges.","s":["Sometimes criminals will make fraudulent charges using unauthorized credit cards.","If you receive a charge that you did not authorize, you should contact your credit card issuer or bank to dispute the charges."]},{"k":"h","c":0,"t":"Special Cases"},{"k":"p","c":1,"t":"You may not be required to dispute or resolve a ticket through the normal process.","s":["You may not be required to dispute or resolve a ticket through the normal process."]},{"k":"h","c":1,"t":"Deceased Vehicle Owners"},{"k":"p","c":1,"t":"If you are the surviving spouse or heir to a deceased registrant, you can resolve parking and camera violation issues on behalf of the deceased at the Department of Finance Legal Affairs Division’s Parking Enforcement Unit. This includes violations in judgment that may cause the vehicle to be booted or towed. You can go in person to resolve the violations or mail your request.","s":["If you are the surviving spouse or heir to a deceased registrant, you can resolve parking and camera violation issues on behalf of the deceased at the Department of Finance Legal Affairs Division’s Parking Enforcement Unit.","This includes violations in judgment that may cause the vehicle to be booted or towed.","You can go in person to resolve the violations or mail your request."]},{"k":"p","c":1,"t":"Bring or mail a copy of the death certificate, as well as the vehicle’s:","s":["Bring or mail a copy of the death certificate, as well as the vehicle’s:"]},{"k":"h","c":1,"t":"Original title"},{"k":"h","c":1,"t":"New registration stub"},{"k":"h","c":1,"t":"New insurance card"},{"k":"p","c":1,"t":"New metal plates or letters of administration obtained from the Surrogate Court in the country where the deceased passed away","s":["New metal plates or letters of administration obtained from the Surrogate Court in the country where the deceased passed away"]},{"k":"p","c":1,"t":"Mail or visit:","s":["Mail or visit:"]},{"k":"h","c":1,"t":"DOF Legal Affairs Division"},{"k":"h","c":1,"t":"Parking Enforcement Unit"},{"k":"h","c":1,"t":"345 Adams Street, 5th Floor"},{"k":"h","c":1,"t":"Brooklyn, NY 11201"},{"k":"h","c":1,"t":"Diplomatic and Consular Vehicles"},{"k":"p","c":1,"t":"The Diplomatic Parking Review Panel provides information and assistance with parking tickets given to diplomatic and consular vehicles with license plates issued by the Department of State.","s":["The Diplomatic Parking Review Panel provides information and assistance with parking tickets given to diplomatic and consular vehicles with license plates issued by the Department of State."]},{"k":"p","c":1,"t":"To fight a parking ticket, request and complete the Response Form for Diplomatic and Consular Personnel. Mail it and the original notice of the parking violation you received along with any supporting documentation to:","s":["To fight a parking ticket, request and complete the Response Form for Diplomatic and Consular Personnel.","Mail it and the original notice of the parking violation you received along with any supporting documentation to:"]},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Diplomatic Parking Review Panel"},{"k":"h","c":1,"t":"66 John Street, 3rd Floor"},{"k":"h","c":1,"t":"New York, NY 10038"},{"k":"p","c":1,"t":"Keep copies of everything you submit.","s":["Keep copies of everything you submit."]},{"k":"p","c":1,"t":"Learn more about resolving violations issued to diplomatic and consular vehicles.","s":["Learn more about resolving violations issued to diplomatic and consular vehicles."]},{"k":"h","c":1,"t":"Disability Parking Permit, Hangtag, or Waiver"},{"k":"p","c":1,"t":"You may park in a designated marked disability parking space with any of the following displayed:","s":["You may park in a designated marked disability parking space with any of the following displayed:"]},{"k":"h","c":1,"t":"A New York City-issued disability parking permit"},{"k":"h","c":1,"t":"A blue New York State disability parking permit hangtag"},{"k":"h","c":1,"t":"An outside City/State-issued disability parking permit"},{"k":"h","c":1,"t":"An outside City/State-issued hangtag"},{"k":"h","c":1,"t":"An outside City/State-issued parking waiver"},{"k":"p","c":1,"t":"These permits are only for off-street marked spaces. Only the New York City-issued disability parking permit is valid for on-street parking. These rectangular placards should be displayed in full view on the driver's side dashboard so that ticket-issuing agents can see them.","s":["These permits are only for off-street marked spaces.","Only the New York City-issued disability parking permit is valid for on-street parking.","These rectangular placards should be displayed in full view on the driver's side dashboard so that ticket-issuing agents can see them."]},{"k":"p","c":1,"t":"If you received a parking ticket while parked in an authorized spot and you want to dispute the ticket, you must request a hearing in writing by mail.","s":["If you received a parking ticket while parked in an authorized spot and you want to dispute the ticket, you must request a hearing in writing by mail."]},{"k":"p","c":1,"t":"Camera violations are not dismissible, even if the registrant has a disability parking permit, hangtag, or waiver.","s":["Camera violations are not dismissible, even if the registrant has a disability parking permit, hangtag, or waiver."]},{"k":"p","c":1,"t":"With your written request, you must include:","s":["With your written request, you must include:"]},{"k":"h","c":1,"t":"The ticket number"},{"k":"h","c":1,"t":"Your license plate number"},{"k":"h","c":1,"t":"A copy of your permit, hangtag, or waiver"},{"k":"p","c":1,"t":"A statement that you have a disability parking permit, hangtag, or waiver, and that you were parked in an authorized spot.","s":["A statement that you have a disability parking permit, hangtag, or waiver, and that you were parked in an authorized spot."]},{"k":"p","c":1,"t":"Mail your request and your documentation to:","s":["Mail your request and your documentation to:"]},{"k":"h","c":1,"t":"NYC Department of Finance"},{"k":"h","c":1,"t":"Advocacy Unit"},{"k":"h","c":1,"t":"66 John Street, 3rd Floor"},{"k":"h","c":1,"t":"New York, NY 10038"},{"k":"h","c":1,"t":"Government Employees on Official Business"},{"k":"p","c":1,"t":"If you are a City, State, or Federal Government employee who got a parking ticket while on official business, contact the Official Business Defense (OBD) Liaison at your agency for information and assistance.","s":["If you are a City, State, or Federal Government employee who got a parking ticket while on official business, contact the Official Business Defense (OBD) Liaison at your agency for information and assistance."]},{"k":"h","c":0,"t":"Violation Not Found"},{"k":"p","c":1,"t":"Parking ticket information is available online within five business days of the date of the violation. If the ticket was handwritten and not computer-generated, it will usually take about 10 to 14 days, but could take longer.","s":["Parking ticket information is available online within five business days of the date of the violation.","If the ticket was handwritten and not computer-generated, it will usually take about 10 to 14 days, but could take longer."]},{"k":"p","c":1,"t":"Bus lane, red light, and weigh-in-motion camera Notices of Liability (NOL) are mailed about 30 days after the violation occurred. Speed camera NOLs are mailed in about 14 days.","s":["Bus lane, red light, and weigh-in-motion camera Notices of Liability (NOL) are mailed about 30 days after the violation occurred.","Speed camera NOLs are mailed in about 14 days."]},{"k":"p","c":1,"t":"You don't need to wait until the ticket or violation has been entered into the system to pay or dispute it. If the violation isn't in the system yet, you won't be able to view a digital copy, but you can still pay it or fight it through any payment or dispute method. If you are paying online or using the app, make sure you type in the correct ticket or NOL number and the amount you want to pay (partial or total).","s":["You don't need to wait until the ticket or violation has been entered into the system to pay or dispute it.","If the violation isn't in the system yet, you won't be able to view a digital copy, but you can still pay it or fight it through any payment or dispute method.","If you are paying online or using the app, make sure you type in the correct ticket or NOL number and the amount you want to pay (partial or total)."]},{"k":"h","c":1,"t":"Violations Older Than a Year"},{"k":"p","c":1,"t":"One year after a parking ticket or camera violation has been paid or dismissed, the ticket information is archived and will no longer be available online.","s":["One year after a parking ticket or camera violation has been paid or dismissed, the ticket information is archived and will no longer be available online."]},{"k":"p","c":1,"t":"If a parking ticket isn't paid, it will go into judgment about 100 days after it was issued, a camera violation will go into judgment about 75 days after it was issued.","s":["If a parking ticket isn't paid, it will go into judgment about 100 days after it was issued, a camera violation will go into judgment about 75 days after it was issued."]},{"k":"h","c":1,"t":"Traffic Violations"},{"k":"p","c":1,"t":"Traffic violations (moving violations) won't appear in the Department of Finance's system. You need to pay or dispute them with the New York State Department of Motor Vehicles.","s":["Traffic violations (moving violations) won't appear in the Department of Finance's system.","You need to pay or dispute them with the New York State Department of Motor Vehicles."]},{"k":"p","c":1,"t":"For more information about moving violations, visit the Traffic Ticket page.","s":["For more information about moving violations, visit the Traffic Ticket page."]},{"k":"p","c":0,"t":"Need more help?","s":["Need more help?"]},{"k":"p","c":0,"t":"Contact the Department of Finance or visit a DOF Business Center if you have any other issues or questions about parking and camera violations. Make sure to include or bring receipts or reference numbers. For credit and debit card transactions, you may be asked for the last four digits of your card number.","s":["Contact the Department of Finance or visit a DOF Business Center if you have any other issues or questions about parking and camera violations.","Make sure to include or bring receipts or reference numbers.","For credit and debit card transactions, you may be asked for the last four digits of your card number."]},{"k":"p","c":0,"t":"If you have already contacted the Department of Finance about an issue and were unable to resolve it, visit the Parking Ticket or Camera Violation Advocate page to learn how to get help.","s":["If you have already contacted the Department of Finance about an issue and were unable to resolve it, visit the Parking Ticket or Camera Violation Advocate page to learn how to get help."]}],"unknown_hidden":[]};
